ops.find:
package com.cricketsim.logic

/**
 * One saved career of the My Player mode

    val stage: String = "",
    val homeClub: String = "",
    val pendingCollege: Boolean = false
) {

ops.replace:
    // These two are nullable on purpose: a career saved before this part has no value for them, and Gson then leaves a String as null (it skips the default),
    // which crashed every screen that read it. They keep their saved names ("stage", "homeClub") and are read through [stage] and [homeClub].
    @field:SerializedName("stage") val stageSaved: String? = null,
    @field:SerializedName("homeClub") val homeClubSaved: String? = null,
    val pendingCollege: Boolean = false
) {
    /** "" (district club and above, as always), "School" or "College". Never null, whatever the save held. */
    val stage: String get() = stageSaved ?: ""

    /** The district club he joins when college ends ("" for a career that is not a student). */
    val homeClub: String get() = homeClubSaved ?: ""

ops.find:
val careerPid = before.careerPlayerId
if (careerPid != null && skipping) {
    val keeperId = before.bowlingTeam.wicketkeeperId
        ?: before.bowlingTeam.players.find { it.role == com.cricketsim.logic.PlayerRole.WICKETKEEPER }?.id
    if (!(careerPid == keeperId && chance.fielderId == keeperId)) return null
}

ops.replace:
val careerPid = before.careerPlayerId
if (careerPid != null) {
    // Career mode: only the chances that come to OUR player (a catch he takes, a stumping if he keeps wicket, a ball he stops),
    // never his team-mates' or the computer's.
    if (chance.fielderId != careerPid) return null
    // And only while he is watching: "Skip to my turn" hands the fielding to the computer, except for the wicketkeeper.
    if (skipping) {
        val keeperId = before.bowlingTeam.wicketkeeperId
            ?: before.bowlingTeam.players.find { it.role == com.cricketsim.logic.PlayerRole.WICKETKEEPER }?.id
        if (careerPid != keeperId) return null
    }
}

